package com.orderflow.notification.security;import com.orderflow.platform.error.ErrorCode;import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.IOException;import java.util.UUID;import org.springframework.http.HttpStatus;import org.springframework.security.core.*;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.security.oauth2.server.resource.authentication.JwtAuthenticationToken;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;@Component public class RevocationValidationFilter extends OncePerRequestFilter{private final RevocationStateService s;private final ApiSecurityErrorWriter w;public RevocationValidationFilter(RevocationStateService s,ApiSecurityErrorWriter w){this.s=s;this.w=w;}protected void doFilterInternal(HttpServletRequest q,HttpServletResponse p,FilterChain c)throws ServletException,IOException{if(q.getRequestURI().startsWith("/actuator/")){c.doFilter(q,p);return;}Authentication a=SecurityContextHolder.getContext().getAuthentication();if(!(a instanceof JwtAuthenticationToken t)||!a.isAuthenticated()){c.doFilter(q,p);return;}Number v=t.getToken().getClaim("token_version");var x=s.validate(t.getToken().getId(),UUID.fromString(t.getToken().getSubject()),v==null?-1:v.longValue());if(x==RevocationStateService.Validation.VALID){c.doFilter(q,p);return;}boolean u=x==RevocationStateService.Validation.UNAVAILABLE;w.write(q,p,u?HttpStatus.SERVICE_UNAVAILABLE:HttpStatus.UNAUTHORIZED,u?ErrorCode.SECURITY_STATE_UNAVAILABLE:ErrorCode.TOKEN_REVOKED,u?"Security state is temporarily unavailable.":"The access token has been revoked or superseded.");}}
